def hot_spots(records, top):
    totals = {}
    for name, ms in records:
        totals[name] = totals.get(name, 0) + ms
    ranked = sorted(totals.items(), key=lambda item: (-item[1], item[0]))
    return [[name, ms] for name, ms in ranked[:top]]

